      const releaseDelta=songNow-(session.releaseTargetMs+session.offsetMs);
      const missAt=RHYTHM_RELEASE_AUTO_MISS_ARM_MS+rhythmReleaseWaitMs();
      if(releaseDelta>=missAt)return true;
