// 4つ目は曲のつなぎ目(2026-10-03・元の曲の録音を切り貼りした short ver.)。[[つなぎ目の時刻ms, そこから先の拍のずれms], …]。
// 5つ目は拍のずれの曲線(2026-10-05・テンポが少しずつ変わる曲)。[[時刻ms, ずれms], …] を直線でつなぐ。
// 書いていない曲は今までどおり(つなぎ目・曲線なし)
const rhythmSongBeatGrid=songId=>{const row=RHYTHM_SONG_BEATS[songId];if(!Array.isArray(row))return null;const [beatMs,zeroMs,bar]=row.slice(0,3).map(Number);
  const splices=Array.isArray(row[3])?row[3].filter(s=>Array.isArray(s)&&Number.isFinite(Number(s[0]))&&Number.isFinite(Number(s[1]))).map(s=>[Number(s[0]),Number(s[1])]).sort((a,b)=>a[0]-b[0]):[];
  const curve=Array.isArray(row[4])?row[4].filter(s=>Array.isArray(s)&&Number.isFinite(Number(s[0]))&&Number.isFinite(Number(s[1]))).map(s=>[Number(s[0]),Number(s[1])]).sort((a,b)=>a[0]-b[0]):[];
  return beatMs>50&&Number.isFinite(zeroMs)&&bar>=1?{beatMs,zeroMs,bar:Math.round(bar),splices,curve}:null;};
// 拍のずれの曲線の、時刻 ms でのずれ(両端より外は端の値)
const rhythmBeatCurveAt=(grid,ms)=>{const c=grid&&Array.isArray(grid.curve)?grid.curve:[];if(c.length<2)return 0;if(ms<=c[0][0])return c[0][1];
  for(let i=1;i<c.length;i++)if(ms<=c[i][0]){const [x0,y0]=c[i-1],[x1,y1]=c[i];return y0+(y1-y0)*(ms-x0)/(x1-x0);}return c[c.length-1][1];};
// 曲の時刻 ms の拍の頭(つなぎ目より後ろは、そのずれを足す)
const rhythmBeatZeroAt=(grid,ms)=>{let zero=Number(grid&&grid.zeroMs)||0;if(grid&&Array.isArray(grid.splices))for(const [at,shift] of grid.splices)if(ms>=at)zero=grid.zeroMs+shift;return zero+rhythmBeatCurveAt(grid,ms);};
// つなぎ目の前の格子で数えた拍の時刻 t0 を、曲の時刻へ直す(つなぎ目より後ろに来る拍はずれを足す)
const rhythmBeatLineTime=(grid,t0)=>{let t=t0;if(grid&&Array.isArray(grid.splices))for(const [at,shift] of grid.splices)if(t0+shift>=at)t=t0+shift;return t+rhythmBeatCurveAt(grid,t0);};
