      const hull=[[Math.min(fx,fx+sgn*sd,fx-(sgn<0?sd:0)),fy-th],[Math.max(fx+fw,fx+fw+(sgn>0?sd:0)),fy-th],[Math.max(fx+fw,fx+fw+(sgn>0?sd:0)),fy+fh],[Math.min(fx,fx-(sgn<0?sd:0)),fy+fh]];
