        const sgn=cx<(typeof cssW==='number'?cssW/2:cx)?1:-1;
        const fw=hd.w*sizeScale*1.05,fh=Math.max(10,hd.h*1.5),th=Math.max(6,fh*.75),sd=Math.max(3,fw*.1),fx=cx-fw/2,fy=cy-fh/2+th*.35;
