        const g=ctx.createLinearGradient(0,cy-ry,0,cy+ry);g.addColorStop(0,'rgba(254,226,226,1)');g.addColorStop(.5,'rgba(239,68,68,1)');g.addColorStop(1,'rgba(127,29,29,1)');
