      if(!hasSky&&prev.y<-RHYTHM_SLIDE_OFFSCREEN_PX&&p.y<-RHYTHM_SLIDE_OFFSCREEN_PX&&(!RHYTHM_SCROLL.back||rhythmScrollMinAfter(time,note.scrollGroup)>=rhythmScrollPos(time,note.scrollGroup)))break;
